{"solution_py":""""Normalize event timestamps to UTC without mutating input rows."""
from __future__ import annotations

from collections.abc import Iterable, Mapping
from datetime import date, datetime, timedelta, timezone, tzinfo
from zoneinfo import ZoneInfo
import re


def _timezone(value: str) -> tzinfo:
    text = value.strip()
    if text.upper() in {"UTC", "Z", "GMT"}:
        return timezone.utc
    match = re.fullmatch(r"([+-])(\d{2}):?(\d{2})", text)
    if match:
        hours, minutes = int(match.group(2)), int(match.group(3))
        if hours > 23 or minutes > 59:
            raise ValueError(f"invalid timezone offset: {value!r}")
        delta = timedelta(hours=hours, minutes=minutes)
        if match.group(1) == "-":
            delta = -delta
        return timezone(delta)
    return ZoneInfo(text)


def _parse(value: object, naive_tz: tzinfo) -> datetime:
    if isinstance(value, datetime):
        result = value
    elif isinstance(value, date):
        result = datetime.combine(value, datetime.min.time())
    elif isinstance(value, str):
        text = value.strip()
        if text.endswith(("Z", "z")):
            text = text[:-1] + "+00:00"
        result = datetime.fromisoformat(text)
    else:
        raise TypeError(f"unsupported timestamp value: {type(value).__name__}")
    if result.tzinfo is None:
        result = result.replace(tzinfo=naive_tz)
    return result


def _utc_text(value: object, naive_tz: tzinfo) -> str:
    result = _parse(value, naive_tz).astimezone(timezone.utc)
    return result.isoformat().replace("+00:00", "Z")


def migrate_rows(
    rows: Iterable[Mapping[str, object]], default_timezone: str
) -> list[dict[str, object]]:
    """Return copied rows with their event timestamp represented in UTC."""
    local_tz = _timezone(default_timezone)
    migrated: list[dict[str, object]] = []
    for row in rows:
        copied = dict(row)
        if "occurred_at_utc" in row:
            if row["occurred_at_utc"] is not None:
                copied["occurred_at_utc"] = _utc_text(
                    row["occurred_at_utc"], timezone.utc
                )
        elif "occurred_at" in row and row["occurred_at"] is not None:
            copied["occurred_at_utc"] = _utc_text(row["occurred_at"], local_tz)
        migrated.append(copied)
    return migrated
